// High Tide — data visuals for steering, numbers and plan. Every value comes from data.js
// (generated by model/design.py) or the archived model runs.
import { D } from './data.js';

const NS = 'http://www.w3.org/2000/svg';
const $ = (s, r = document) => r.querySelector(s);
const fmt = (v, d = 0) => Number(v).toLocaleString('en', { minimumFractionDigits: d, maximumFractionDigits: d });
const C = { intake: '#e0533a', clear: '#22a875', cue: '#9b6ff0', air: '#0e9cad', none: '#5d7480' };

// ───────── shared tooltip ─────────
const tip = document.createElement('div'); tip.className = 'tip'; document.body.appendChild(tip);
function bindTip(node, html) {
  node.addEventListener('pointerenter', () => { tip.innerHTML = html; tip.classList.add('is-on'); });
  node.addEventListener('pointermove', (e) => { tip.style.left = `${e.clientX + 14}px`; tip.style.top = `${e.clientY + 14}px`; });
  node.addEventListener('pointerleave', () => tip.classList.remove('is-on'));
}

// ───────── Pull vs swimmer ─────────
function pullChart() {
  const svg = $('#pull-chart'); if (!svg) return;
  const W = 640, H = 330, m = { l: 52, r: 18, t: 18, b: 40 };
  const X0 = 6.3, X1 = 0.4;                       // km from intakes, left = offshore
  const x = (km) => m.l + (X0 - km) / (X0 - X1) * (W - m.l - m.r);
  const Y0 = Math.log(2), Y1 = Math.log(40);
  const y = (cm) => H - m.b - (Math.log(cm) - Y0) / (Y1 - Y0) * (H - m.t - m.b);
  const pts = [...D.pull_profile].sort((a, b) => b.dist_km - a.dist_km).map((p) => [p.dist_km, p.u_m_s * 100]);
  const swim = D.phys.swim_speed * 100, nr = D.no_return_km, gate = D.dist_gate_to_intake_m / 1000;
  let s = '';
  // zones
  s += `<rect x="${m.l}" y="${m.t}" width="${x(nr) - m.l}" height="${H - m.t - m.b}" fill="rgba(92,255,176,.06)"/>`;
  s += `<rect x="${x(nr)}" y="${m.t}" width="${W - m.r - x(nr)}" height="${H - m.t - m.b}" fill="rgba(255,90,60,.07)"/>`;
  // grid + y ticks
  for (const v of [2, 5, 10, 20, 40]) s += `<line x1="${m.l}" x2="${W - m.r}" y1="${y(v)}" y2="${y(v)}" stroke="rgba(205,188,255,.1)"/><text x="${m.l - 8}" y="${y(v) + 3}" text-anchor="end" class="mono" font-size="9" fill="#8d84aa">${v}</text>`;
  s += `<text x="12" y="${m.t + 4}" class="mono" font-size="8.5" fill="#8d84aa" transform="rotate(-90 12 ${m.t + 4})" text-anchor="end">CM/S · LOG</text>`;
  for (const k of [6, 5, 4, 3, 2, 1]) s += `<text x="${x(k)}" y="${H - m.b + 16}" text-anchor="middle" class="mono" font-size="9" fill="#8d84aa">${k} km</text>`;
  s += `<text x="${W - m.r}" y="${H - 6}" text-anchor="end" class="mono" font-size="8.5" fill="#8d84aa">DISTANCE FROM THE INTAKES →</text>`;
  // swim line
  s += `<line x1="${m.l}" x2="${W - m.r}" y1="${y(swim)}" y2="${y(swim)}" stroke="#5cffb0" stroke-width="1.5" stroke-dasharray="5 5"/>`;
  s += `<text x="${W - m.r - 8}" y="${y(swim) + 16}" text-anchor="end" class="mono" font-size="9.5" fill="#5cffb0">BLUE BLUBBER SWIM SPEED · ${swim.toFixed(1)} CM/S</text>`;
  // area + line
  const line = pts.map((p) => `${x(p[0]).toFixed(1)},${y(p[1]).toFixed(1)}`).join(' ');
  s += `<polygon points="${x(pts[0][0])},${H - m.b} ${line} ${x(pts[pts.length - 1][0])},${H - m.b}" fill="url(#pullG)" opacity=".55"/>`;
  s += `<defs><linearGradient id="pullG" x1="0" x2="1"><stop offset="0" stop-color="#00ebff" stop-opacity=".25"/><stop offset="1" stop-color="#ff5a3c" stop-opacity=".55"/></linearGradient></defs>`;
  s += `<polyline points="${line}" fill="none" stroke="#e9f1f2" stroke-width="2"/>`;
  pts.forEach((p) => { s += `<circle cx="${x(p[0])}" cy="${y(p[1])}" r="4" fill="#03080c" stroke="#e9f1f2" stroke-width="1.5"/>`; });
  // markers
  s += `<line x1="${x(nr)}" x2="${x(nr)}" y1="${m.t}" y2="${H - m.b}" stroke="#ffc24a" stroke-dasharray="2 4"/>`;
  s += `<text x="${x(nr) + 6}" y="${m.t + 12}" class="mono" font-size="9.5" fill="#ffc24a">POINT OF NO RETURN · ${nr} KM</text>`;
  s += `<line x1="${x(gate)}" x2="${x(gate)}" y1="${m.t + 22}" y2="${H - m.b}" stroke="#00ebff" stroke-width="2"/>`;
  s += `<text x="${x(gate) - 6}" y="${m.t + 34}" text-anchor="end" class="mono" font-size="9.5" fill="#00ebff">GATE</text>`;
  s += `<text x="${m.l + 10}" y="${H - m.b - 10}" class="mono" font-size="9" fill="#5cffb0" opacity=".9">CAN STILL SWIM OUT</text>`;
  s += `<text x="${W - m.r - 10}" y="${H - m.b - 10}" text-anchor="end" class="mono" font-size="9" fill="#ff9a85">ONE-WAY TRIP</text>`;
  const cpt = pts[pts.length - 1];
  s += `<text x="${x(cpt[0]) - 8}" y="${y(cpt[1]) - 12}" text-anchor="end" font-family="VG5000" font-size="20" fill="#ff9a85">${cpt[1].toFixed(0)} cm/s</text>`;
  s += `<text x="${x(pts[0][0])}" y="${y(pts[0][1]) - 34}" font-family="VG5000" font-size="20" fill="#e9f1f2">${pts[0][1].toFixed(0)} cm/s</text>`;
  // hover targets
  s += `<g class="hits">${pts.map((p) => `<rect x="${x(p[0]) - 18}" y="${m.t}" width="36" height="${H - m.t - m.b}" fill="transparent" data-km="${p[0]}" data-u="${p[1].toFixed(1)}"/>`).join('')}</g>`;
  svg.innerHTML = s;
  svg.querySelectorAll('.hits rect').forEach((r) => {
    const prof = D.pull_profile.find((p) => p.dist_km === +r.dataset.km);
    bindTip(r, `<b>${r.dataset.km} km</b> from the intakes<br>pull ≈ ${r.dataset.u} cm/s<br>width ${fmt(prof.width_m)} m × depth ${prof.depth_m} m`);
  });
}

// ───────── horizontal bars ─────────
function hbars(el, rows, unit = '') {
  if (!el) return;
  const max = Math.max(...rows.map((r) => r.v));
  el.innerHTML = rows.map((r) => `<div class="hbar"><span class="hbar__l">${r.l}</span><div class="hbar__t" style="--w:${(r.v / max * 78).toFixed(1)}%;--c:${r.c}"><i></i><b>${r.t ?? fmt(r.v)}${unit}</b></div></div>`).join('');
  el.querySelectorAll('.hbar').forEach((n, i) => bindTip(n, rows[i].tip || `${rows[i].l}: <b>${rows[i].t ?? fmt(rows[i].v)}${unit}</b>`));
}
function adds() {
  const o = (sc) => D.outcomes.find((r) => r.scenario === sc);
  const rev = o('reversal'), weak = o('weak');
  hbars($('#adds-rev'), [
    { l: 'No diversion', v: rev.none, c: C.none },
    { l: 'Corridor', v: rev.ctrl.intake, c: C.air },
    { l: 'Corridor + cues', v: rev.ctrl_cues.intake, c: C.cue },
  ].map((r) => ({ ...r, t: fmt(r.v), tip: `${r.l}: <b>${fmt(r.v, 1)}</b> of 900 reached the intake (3-seed mean)` })));
  hbars($('#adds-weak'), [
    { l: 'No diversion', v: 26, c: C.none },
    { l: 'Corridor', v: weak.ctrl.exit, c: C.air },
    { l: 'Corridor + cues', v: weak.ctrl_cues.exit, c: C.cue },
  ].map((r) => ({ ...r, t: fmt(r.v), tip: `${r.l}: <b>${fmt(r.v, 1)}</b> of 900 cleared outside (3-seed mean)` })));
  hbars($('#adds-air'), [
    { l: 'Corridor', v: weak.ctrl.act / 900 * 100, c: C.air },
    { l: 'Corridor + cues', v: weak.ctrl_cues.act / 900 * 100, c: C.cue },
  ].map((r) => ({ ...r, t: `${r.v.toFixed(0)} %`, tip: `${r.l}: sections × time on = <b>${r.v.toFixed(0)} %</b> of an always-on wall` })));
}

// ───────── where 200 t ends up ─────────
function flow2() {
  const el = $('#flow2'); if (!el) return;
  const names = { normal: ['Steady tide', 'one direction all event'], reversal: ['Tide turns mid-event', 'the hard, realistic case'], delayed: ['Tide turns + 90 s lag', 'slow controller'], surge: ['Bloom surge ×3', 'second half of the event'], power_loss: ['Power cut half-way', 'wall fails off'], blocked_exit: ['Exit blocked', 'nowhere to send them'], zero_response: ['Animals don’t respond', 'bubbles have no effect'] };
  let h = `<div class="f2__legend mono"><span style="--c:${C.none}"><i></i>No diversion</span><span style="--c:${C.air}"><i></i>Corridor (controlled)</span><span style="--c:${C.cue}"><i></i>Corridor + cues (hypothesis)</span></div>`;
  for (const sc of Object.keys(names)) {
    const r = D.outcomes.find((o) => o.scenario === sc);
    const bars = [['No diversion', 200, C.none], ['Corridor', r.ctrl.t_at_screens, C.air], ['Corridor + cues', r.ctrl_cues.t_at_screens, C.cue]];
    h += `<div class="f2"><div class="f2__l">${names[sc][0]}<small>${names[sc][1]}</small></div><div class="f2__bars">${bars.map((b) => `<div class="f2__bar" style="--w:${(b[1] / 200 * 82).toFixed(1)}%;--c:${b[2]}" data-tip="${names[sc][0]} · ${b[0]}: <b>${fmt(b[1], 1)} t</b> of 200 t reach the screens"><i></i><b>${fmt(b[1], b[1] < 10 && b[1] > 0 ? 1 : 0)} t</b></div>`).join('')}</div></div>`;
  }
  el.innerHTML = h;
  el.querySelectorAll('[data-tip]').forEach((n) => bindTip(n, n.dataset.tip));
}

// ───────── bill of materials ─────────
function bom() {
  const el = $('#bom'); if (!el) return;
  el.innerHTML = `<div class="bom__r bom__h"><span>Item</span><span>Qty</span><span>Note</span></div>` + D.bom.map((b) => `<div class="bom__r"><span>${b.item}</span><b>${b.qty}</b><span>${b.note}</span></div>`).join('');
}

// ───────── energy ─────────
function energy() {
  const el = $('#energy'); if (!el) return;
  el.className = 'hbars energy';
  hbars(el, [
    { l: 'Worst case: line + guard', v: D.ops.kw_max_simultaneous, c: C.intake },
    { l: 'Typical event', v: D.ops.kw_gate_typical, c: C.air },
    { l: 'Weak flow · corridor', v: D.ops.kw_gate_weak, c: C.air },
    { l: 'Weak flow · + cues', v: D.ops.kw_gate_weak_cues, c: C.cue },
  ], ' kW');
}

// ───────── chemistry table ─────────
function chem() {
  const el = $('#chem-table'); if (!el) return;
  const rows = D.stick.map((s) => `<tr class="${s.c_ug_L === 5 && s.u === 0.1 ? 'is-mid' : ''}"><td>${s.c_ug_L} µg/L</td><td>${s.u} m/s</td><td>${fmt(s.g_per_h)}</td><td>${fmt(s.kg_per_event, 1)}</td><td>${s.intake_ug_L.toFixed(2)}</td><td>${fmt(s.margin_band_vs_fish_LC50)}×</td></tr>`).join('');
  el.innerHTML = `<table class="ctab"><thead><tr><th>Band target</th><th>Water speed</th><th>g/h</th><th>kg / 12 h</th><th>At pumps µg/L</th><th>Band vs fish LC₅₀</th></tr></thead><tbody>${rows}</tbody><caption>(E)-2-nonenal mass = target × water speed × 300 m active band × 3 m surface layer × 40 % pulse duty. Fish LC₅₀ 5.5 mg/L and algal EC₅₀ 8.0 mg/L are ECOSAR screening estimates from a supplier SDS — not safe thresholds. The effective adult dose is unknown until the assay runs; these brackets size the pumps, tanks and permits.</caption></table>`;
}

// ───────── pilot ladder ─────────
function pilot() {
  const el = $('#pilot-rows'); if (!el) return;
  const lo = Math.log10(1000), hi = Math.log10(1_000_000);
  const pos = (v) => (Math.log10(v) - lo) / (hi - lo) * 80;
  const k = (v) => v >= 1000 ? `${(v / 1000).toFixed(v < 10000 ? 1 : 0)}k` : v;
  el.innerHTML = D.pilot_budget.map((p) => `<div class="prow"><span>${p.stage}</span><div class="prow__t" style="--a:${pos(p.lo).toFixed(1)}%;--w:${(pos(p.hi) - pos(p.lo)).toFixed(1)}%"><i></i><b>AED ${k(p.lo)} – ${k(p.hi)}</b></div></div>`).join('') + `<div class="prow"><span class="mono" style="font-size:8.5px;color:var(--dim)">LOG SCALE · AED 1k → 1M</span><span></span></div>`;
}

// ───────── 26-week plan ─────────
const STREAMS = [
  { n: 'Mobilise & data', o: 'O4', c: '#ffc24a', s: 0, d: 2, del: [['D1', 'Pre-registered protocol'], ['D2', 'ENEC data request (7 items)'], ['D3', '3 compressor + hose quotes']] },
  { n: 'Bench flume & controller', o: 'O1', c: '#00ebff', s: 2, d: 7, del: [['D4', '6 m flume, 6-section rig'], ['D5', 'Deflection curves: 3 angles × 4 currents × 3 air rates']] },
  { n: 'Species ID & assay build', o: 'O2', c: '#a97bff', s: 3, d: 7, del: [['D6', 'COI/16S barcodes, ≥10 vouchers'], ['D7', 'Choice chamber validated: tracer + GC-MS ≥80 % recovery']] },
  { n: 'Cue trials (2 × 2)', o: 'O2·O3', c: '#a97bff', s: 10, d: 9, del: [['D8', 'Trial dataset, ≥30 animals/arm, 72 h welfare']] },
  { n: 'Non-target screen', o: 'O3', c: '#5cffb0', s: 14, d: 7, del: [['D9', 'Algae, copepod, bivalve-larva endpoints at measured exposure']] },
  { n: 'Site & marine-trial design', o: 'O4', c: '#ff5a3c', s: 12, d: 14, del: [['D10', '30-day ADCP + bathymetry with ENEC'], ['D11', 'Trial plan, EAD pre-application, costed BOM']] },
];
const GATES = [
  { g: 1, wk: 2, t: 'Ready to test', c: 'Protocol pre-registered; marine-lab partner and ENEC data contact signed.', pass: 'Start builds', fail: 'Hold, re-scope with ENEC' },
  { g: 2, wk: 9, t: 'The wall works', c: '<b>≥70 %</b> surrogate deflection at 0.2 m/s with ≤1.1 L/s per metre of hose.', pass: 'Size the marine section', fail: 'Double curtain or drop to guard-only' },
  { g: 3, wk: 19, t: 'The nudge is real', c: '<b>≥15 pp</b> more verified exits than bubbles alone, p < 0.05, no excess injury at 72 h.', pass: 'Cues stay in the design', fail: 'Physical-only High Tide' },
  { g: 4, wk: 21, t: 'It’s safe', c: 'No effect on algae, copepods or bivalve larvae at <b>10×</b> the design band.', pass: 'Containment design', fail: 'Chemical layer dropped' },
  { g: 5, wk: 26, t: 'Pilot decision', c: 'Surveyed gate line, quoted 50 m recoverable section, EAD pre-application filed.', pass: 'Marine trial (zero chemicals)', fail: 'Report and stop' },
];
function gantt() {
  const el = $('#gantt'); if (!el) return;
  let h = `<div class="g-head"><div class="g-name mono" style="font-size:8.5px;color:var(--dim)">WORKSTREAM · OBJECTIVE</div><div class="g-weeks">${Array.from({ length: 26 }, (_, i) => `<span>${i % 4 === 0 ? 'W' + (i + 1) : ''}</span>`).join('')}${GATES.map((g) => `<i class="g-gate" style="--s:${g.wk}" data-g="G${g.g}"></i>`).join('')}</div></div>`;
  for (const s of STREAMS) {
    h += `<div class="g-row"><div class="g-name"><b>${s.n}</b><small>${s.o} · WEEKS ${s.s + 1}–${s.s + s.d}</small><div class="g-del">${s.del.map((d) => `<span><b>${d[0]}</b>${d[1]}</span>`).join('')}</div></div><div class="g-track">${GATES.map((g) => `<i class="g-gate" style="--s:${g.wk}" data-g="G${g.g}"></i>`).join('')}<div class="g-bar" style="--s:${s.s};--d:${s.d};--c:${s.c}" data-tip="<b>${s.n}</b><br>weeks ${s.s + 1}–${s.s + s.d}<br>${s.del.map((d) => d[0] + ' · ' + d[1]).join('<br>')}">${s.del.map((d) => d[0]).join(' · ')}</div></div></div>`;
  }
  el.innerHTML = h;
  el.querySelectorAll('[data-tip]').forEach((n) => bindTip(n, n.dataset.tip));
  const ge = $('#gates');
  if (ge) ge.innerHTML = GATES.map((g) => `<article class="gate"><span>G${g.g} · WEEK ${g.wk}</span><h4>${g.t}</h4><p>${g.c}</p><small>PASS → ${g.pass}<br><b>FAIL → ${g.fail}</b></small></article>`).join('');
}

export function buildCharts() { pullChart(); adds(); flow2(); bom(); energy(); chem(); pilot(); gantt(); }
